def to_index_kind(index_kind: str | None) -> str:
    """Convert an index kind to the Azure Cosmos DB NoSQL index kind.

    Args:
        index_kind (str | None): The index kind.

    Returns:
        str: The Azure Cosmos DB NoSQL index kind.
    """
    if index_kind not in INDEX_KIND_MAPPING:
        raise VectorStoreModelException(
            f"Index kind '{index_kind}' is not supported by Azure Cosmos DB NoSQL container."
        )
    return INDEX_KIND_MAPPING[index_kind]


def to_distance_function(distance_function: str | None) -> str:
    """Convert a distance function to the Azure Cosmos DB NoSQL distance function.

    Args:
        distance_function (str | None): The distance function.

    Returns:
        str: The Azure Cosmos DB NoSQL distance function.
    """
    if distance_function not in DISTANCE_FUNCTION_MAPPING:
        raise VectorStoreModelException(
            f"Distance function '{distance_function}' is not supported by Azure Cosmos DB NoSQL container."
        )
    return DISTANCE_FUNCTION_MAPPING[distance_function]


def to_datatype(property_type: str | None) -> str:
    """Convert a property type to the Azure Cosmos DB NoSQL data type.

    Args:
        property_type (str | None): The property type.

    Returns:
        str: The Azure Cosmos DB NoSQL data type.
    """
    if property_type not in DATATYPES_MAPPING:
        raise VectorStoreModelException(
            f"Property type '{property_type}' is not supported by Azure Cosmos DB NoSQL container."
        )
    return DATATYPES_MAPPING[property_type]


def create_default_indexing_policy(data_model_definition: VectorStoreRecordDefinition) -> dict[str, Any]:
    """Create a default indexing policy for the Azure Cosmos DB NoSQL container.

    A default indexing policy is created based on the data model definition and has an automatic indexing policy.

    Args:
        data_model_definition (VectorStoreRecordDefinition): The definition of the data model.

    Returns:
        dict[str, Any]: The indexing policy.

    Raises:
        VectorStoreModelException: If the field is not full text searchable and not filterable.
    """
    indexing_policy: dict[str, Any] = {
        "automatic": True,
        "includedPaths": [
            {
                "path": "/*",
            }
        ],
        "excludedPaths": [
            {
                "path": '/"_etag"/?',
            }
        ],
        "vectorIndexes": [],
    }

    for field in data_model_definition.fields.values():
        if isinstance(field, VectorStoreRecordVectorField):
            indexing_policy["vectorIndexes"].append(
                {
                    "path": f"/{field.name}",
                    "type": to_index_kind(field.index_kind),
                }
            )
            # For vector fields, if the index kind is not flat, the vector path needs to be excluded from
            # the regular indexing policy, otherwise the container creation will fail.
            if field.index_kind != "flat":
                indexing_policy["excludedPaths"].append(
                    {
                        "path": f"/{field.name}/*",
                    }
                )

    return indexing_policy


def create_default_vector_embedding_policy(data_model_definition: VectorStoreRecordDefinition) -> dict[str, Any]:
    """Create a default vector embedding policy for the Azure Cosmos DB NoSQL container.

    A default vector embedding policy is created based on the data model definition.

    Args:
        data_model_definition (VectorStoreRecordDefinition): The definition of the data model.

    Returns:
        dict[str, Any]: The vector embedding policy.

    Raises:
        VectorStoreModelException: If the datatype or distance function is not supported by Azure Cosmos DB NoSQL.
    """
    vector_embedding_policy: dict[str, Any] = {"vectorEmbeddings": []}

    for field in data_model_definition.fields.values():
        if isinstance(field, VectorStoreRecordVectorField):
            vector_embedding_policy["vectorEmbeddings"].append(
                {
                    "path": f"/{field.name}",
                    "dataType": to_datatype(field.property_type),
                    "distanceFunction": to_distance_function(field.distance_function),
                    "dimensions": field.dimensions,
                }
            )

    return vector_embedding_policy


class CosmosClientWrapper(CosmosClient):
    """Wrapper to make sure the connection is closed when the object is deleted."""

    def __del__(self) -> None:
        """Close the connection.

        This is called when the object is deleted.
        """
        with contextlib.suppress(Exception):
            asyncio.get_running_loop().create_task(self.close())
